patch_result.patch:
--- a/blosc/frame.c
+++ b/blosc/frame.c
@@ -2684,8 +2684,8 @@
     BLOSC_TRACE_ERROR("Cannot get the chunk in position %d.", nchunk);
     return BLOSC2_ERROR_DATA;
   }
-  if (chunk_cbytes < (signed)sizeof(int32_t)) {
-    /* Not enough input to read `nbytes` */
+  if (chunk_cbytes < BLOSC_MIN_HEADER_LENGTH) {
+    /* Not enough input to read a complete Blosc header */
     return BLOSC2_ERROR_READ_BUFFER;
   }

args:
@@ -2684,10 +2684,10 @@ int frame_decompress_chunk(blosc2_context *dctx, blosc2_frame_s* frame, int nch
     BLOSC_TRACE_ERROR("Cannot get the chunk in position %d.", nchunk);
     return BLOSC2_ERROR_DATA;
   }
-  if (chunk_cbytes < (signed)sizeof(int32_t)) {
-    /* Not enough input to read `nbytes` */
+  if (chunk_cbytes < BLOSC_MIN_HEADER_LENGTH) {
+    /* Not enough input to read a complete Blosc header */
     return BLOSC2_ERROR_READ_BUFFER;
   }

